/* SMAA 1x, Metal port of iryoku/smaa SMAA.hlsl (MIT; ../../../smaa/LICENSE.txt).
   The orthogonal search / blend started from Odyssey's odyssey_gfx_present.inc at e3f7e9d4.
   totk_smaa_config.h supplies the reference preset limits; Low and Medium omit diagonals/corners. High and Ultra
   preserve corners with 25% rounding. No temporal history, jitter, predication or game shaders. Subsample indices are zero. */
static const char *totk_smaa_msl =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct V { float4 p [[position]]; float2 uv; };\n"
"struct SP { float threshold; uint steps,diagonal; float corner,blend; uint srgb,pad0,pad1; };\n"
"vertex V smaa_vs(uint id [[vertex_id]]) { float2 uv = float2((id << 1) & 2, id & 2); return {float4(uv * float2(2,-2) + float2(-1,1),0,1),uv}; }\n"
"static float4 metrics(texture2d<float> t) { return float4(1.0 / float2(t.get_width(),t.get_height()),float2(t.get_width(),t.get_height())); }\n"
"static float lum(float3 c, uint srgb) { if (srgb) c = select(12.92*c,1.055*pow(max(c,0.0),float3(1.0/2.4))-0.055,c>0.0031308); return dot(c,float3(.2126,.7152,.0722)); }\n"
"fragment float4 smaa_edge(V in [[stage_in]], texture2d<float> t [[texture(0)]], sampler li [[sampler(0)]], constant SP& p [[buffer(0)]]) {\n"
" float2 uv=in.uv,px=metrics(t).xy; float L=lum(t.sample(li,uv).rgb,p.srgb),l=lum(t.sample(li,uv-px*float2(1,0)).rgb,p.srgb),u=lum(t.sample(li,uv-px*float2(0,1)).rgb,p.srgb);\n"
" float4 d; d.xy=abs(L-float2(l,u)); float2 e=step(p.threshold,d.xy); if(dot(e,float2(1))==0) discard_fragment();\n"
" d.zw=abs(L-float2(lum(t.sample(li,uv+px*float2(1,0)).rgb,p.srgb),lum(t.sample(li,uv+px*float2(0,1)).rgb,p.srgb))); float2 mx=max(d.xy,d.zw);\n"
" d.zw=abs(float2(l,u)-float2(lum(t.sample(li,uv-px*float2(2,0)).rgb,p.srgb),lum(t.sample(li,uv-px*float2(0,2)).rgb,p.srgb))); mx=max(mx,d.zw);\n"
" e*=step(max(mx.x,mx.y),2.0*d.xy); return float4(e,0,0); }\n"
"static float2 diag_decode(float2 e) { e.r*=abs(5.0*e.r-3.75); return round(e); }\n"
"static float4 diag_decode(float4 e) { e.rb*=abs(5.0*e.rb-3.75); return round(e); }\n"
"static float2 diag_search(texture2d<float> et,sampler li,float2 tc,float2 dir,float4 m,bool second,thread float2& e,uint steps) {\n"
" float4 c=float4(tc,-1,1); if(second)c.x+=.25*m.x;\n"
" while(c.z<float(steps)-1.0 && c.w>.9) { c.xyz+=float3(m.xy,1)*float3(dir,1); e=et.sample(li,c.xy).rg; if(second)e=diag_decode(e); c.w=dot(e,float2(.5)); } return c.zw; }\n"
"static float2 diag_area(texture2d<float> at,sampler li,float2 d,float2 e) { float2 tc=(20.0*e+d+.5)/float2(160,560); tc.x+=.5; return at.sample(li,tc).rg; }\n"
"static float2 diag_weights(texture2d<float> et,texture2d<float> at,sampler li,float2 tc,float2 e,float4 m,uint steps) {\n"
" float2 w=0,end=0; float4 d;\n"
" if(e.r>0) { d.xz=diag_search(et,li,tc,float2(-1,1),m,false,end,steps); d.x+=float(end.y>.9); } else d.xz=0;\n"
" d.yw=diag_search(et,li,tc,float2(1,-1),m,false,end,steps);\n"
" if(d.x+d.y>2) { float4 co=float4(-d.x+.25,d.x,d.y,-d.y-.25)*m.xyxy+tc.xyxy,c;\n"
" c.xy=et.sample(li,co.xy,int2(-1,0)).rg; c.zw=et.sample(li,co.zw,int2(1,0)).rg; c.yxwz=diag_decode(c);\n"
" float2 cc=2.0*c.xz+c.yw; cc=select(cc,float2(0),d.zw>=.9); w+=diag_area(at,li,d.xy,cc); }\n"
" d.xz=diag_search(et,li,tc,float2(-1,-1),m,true,end,steps);\n"
" if(et.sample(li,tc,int2(1,0)).r>0) { d.yw=diag_search(et,li,tc,float2(1,1),m,true,end,steps); d.y+=float(end.y>.9); } else d.yw=0;\n"
" if(d.x+d.y>2) { float4 co=float4(-d.x,-d.x,d.y,d.y)*m.xyxy+tc.xyxy,c;\n"
" c.x=et.sample(li,co.xy,int2(-1,0)).g; c.y=et.sample(li,co.xy,int2(0,-1)).r; c.zw=et.sample(li,co.zw,int2(1,0)).gr;\n"
" float2 cc=2.0*c.xz+c.yw; cc=select(cc,float2(0),d.zw>=.9); w+=diag_area(at,li,d.xy,cc).gr; } return w; }\n"
"static float slen(texture2d<float> st,sampler pt,float2 e,float off) { float2 scale=float2(66,33)*float2(.5,-1)+float2(-1,1),bias=float2(66,33)*float2(off,1)+float2(.5,-.5); return st.sample(pt,(scale*e+bias)/float2(64,16)).r; }\n"
"static float xl(texture2d<float> et,texture2d<float> st,sampler li,sampler pt,float2 tc,float end,float4 m) { float2 e=float2(0,1);\n"
" while(tc.x>end && e.g>.8281 && e.r==0) { e=et.sample(li,tc).rg; tc.x-=2*m.x; } return tc.x+m.x*(3.25-(255.0/127.0)*slen(st,pt,e,0)); }\n"
"static float xr(texture2d<float> et,texture2d<float> st,sampler li,sampler pt,float2 tc,float end,float4 m) { float2 e=float2(0,1);\n"
" while(tc.x<end && e.g>.8281 && e.r==0) { e=et.sample(li,tc).rg; tc.x+=2*m.x; } return tc.x-m.x*(3.25-(255.0/127.0)*slen(st,pt,e,.5)); }\n"
"static float yu(texture2d<float> et,texture2d<float> st,sampler li,sampler pt,float2 tc,float end,float4 m) { float2 e=float2(1,0);\n"
" while(tc.y>end && e.r>.8281 && e.g==0) { e=et.sample(li,tc).rg; tc.y-=2*m.y; } return tc.y+m.y*(3.25-(255.0/127.0)*slen(st,pt,e.gr,0)); }\n"
"static float yd(texture2d<float> et,texture2d<float> st,sampler li,sampler pt,float2 tc,float end,float4 m) { float2 e=float2(1,0);\n"
" while(tc.y<end && e.r>.8281 && e.g==0) { e=et.sample(li,tc).rg; tc.y+=2*m.y; } return tc.y-m.y*(3.25-(255.0/127.0)*slen(st,pt,e.gr,.5)); }\n"
"static float2 area(texture2d<float> at,sampler li,float2 d,float e1,float e2) { return at.sample(li,(16.0*round(4.0*float2(e1,e2))+d+.5)/float2(160,560)).rg; }\n"
"static float2 corner(texture2d<float> et,sampler li,float4 co,float2 d,bool vertical,float rounding) {\n"
" float2 lr=step(d.xy,d.yx),r=(1.0-rounding)*lr/(lr.x+lr.y),f=1;\n"
" if(vertical) { f.x-=r.x*et.sample(li,co.xy,int2(1,0)).g+r.y*et.sample(li,co.zw,int2(1,1)).g;\n"
" f.y-=r.x*et.sample(li,co.xy,int2(-2,0)).g+r.y*et.sample(li,co.zw,int2(-2,1)).g; }\n"
" else { f.x-=r.x*et.sample(li,co.xy,int2(0,1)).r+r.y*et.sample(li,co.zw,int2(1,1)).r;\n"
" f.y-=r.x*et.sample(li,co.xy,int2(0,-2)).r+r.y*et.sample(li,co.zw,int2(1,-2)).r; } return saturate(f); }\n"
"fragment float4 smaa_weight(V in [[stage_in]],texture2d<float> et [[texture(0)]],texture2d<float> at [[texture(1)]],texture2d<float> st [[texture(2)]],sampler li [[sampler(0)]],sampler pt [[sampler(1)]],constant SP& p [[buffer(0)]]) {\n"
" float4 m=metrics(et); float2 tc=in.uv,pix=tc*m.zw;\n"
" float4 o0=m.xyxy*float4(-.25,-.125,1.25,-.125)+tc.xyxy,o1=m.xyxy*float4(-.125,-.25,-.125,1.25)+tc.xyxy;\n"
" float4 o2=m.xxyy*float4(-2,2,-2,2)*float(p.steps)+float4(o0.xz,o1.yw),w=0; float2 e=et.sample(pt,tc).rg;\n"
" if(e.g>0) { if(p.diagonal)w.rg=diag_weights(et,at,li,tc,e,m,p.diagonal); if(w.r==-w.g) {\n"
" float3 co; co.x=xl(et,st,li,pt,o0.xy,o2.x,m); co.y=o1.y; float2 d; d.x=co.x; float e1=et.sample(li,co.xy).r;\n"
" co.z=xr(et,st,li,pt,o0.zw,o2.y,m); d.y=co.z; d=abs(round(m.zz*d-pix.xx)); float e2=et.sample(li,co.zy,int2(1,0)).r;\n"
" w.rg=area(at,li,sqrt(d),e1,e2); co.y=tc.y; if(p.diagonal)w.rg*=corner(et,li,co.xyzy,d,false,p.corner); } else e.r=0; }\n"
" if(e.r>0) { float3 co; co.y=yu(et,st,li,pt,o1.xy,o2.z,m); co.x=o0.x; float2 d; d.x=co.y; float e1=et.sample(li,co.xy).g;\n"
" co.z=yd(et,st,li,pt,o1.zw,o2.w,m); d.y=co.z; d=abs(round(m.ww*d-pix.yy)); float e2=et.sample(li,co.xz,int2(0,1)).g;\n"
" w.ba=area(at,li,sqrt(d),e1,e2); co.x=tc.x; if(p.diagonal)w.ba*=corner(et,li,co.xyxz,d,true,p.corner); } return w; }\n"
"fragment float4 smaa_blend(V in [[stage_in]],texture2d<float> t [[texture(0)]],texture2d<float> bt [[texture(1)]],sampler li [[sampler(0)]],constant SP& p [[buffer(0)]]) {\n"
" float4 m=metrics(t),o=m.xyxy*float4(1,0,0,1)+in.uv.xyxy,a; float4 original=t.sample(li,in.uv); if(p.blend<=0)return original;\n"
" a.x=bt.sample(li,o.xy).a; a.y=bt.sample(li,o.zw).g; a.wz=bt.sample(li,in.uv).xz; if(dot(a,float4(1))<1e-5)return original;\n"
" bool h=max(a.x,a.z)>max(a.y,a.w); float4 bo=h?float4(a.x,0,a.z,0):float4(0,a.y,0,a.w);\n"
" float2 bw=h?a.xz:a.yw; bw/=dot(bw,float2(1)); float4 bc=bo*float4(m.xy,-m.xy)+in.uv.xyxy;\n"
" float3 rgb=bw.x*t.sample(li,bc.xy).rgb+bw.y*t.sample(li,bc.zw).rgb; if(p.blend<1)rgb=mix(original.rgb,rgb,p.blend); return float4(rgb,original.a); }\n";
